{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Konklusionen stemmer med rubrikken og vejledningen. Målestokken er erhvervsevne som uddannelsessøgende. Kommunal arbejdsevnevurdering, arbejdsprøvning, særlig arbejdspladsindretning, kontakt til arbejdsgivere, studierelevans, lokale forhold og erhvervsevne efter uddannelsen indgår ikke. Tidligere arbejde kan indgå. Jeg finder ingen af rubrikkens 'material errors'."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fem kritiske elementer er dækket i substans. Det gælder målestok, ikke kommunal vurdering, arbejdsprøvning/indretning/arbejdsgivere, studierelevans/lokale forhold/beskæftigelsessituation og ikke erhvervsevne efter uddannelsen. Svaret nævner ikke udtrykkeligt 'svært ved at finde arbejde' eller 'art og grad'. 'Beskæftigelsessituationen' og 'meget betydelige begrænsninger' er acceptabelt tilsvarende."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret tager hvert af de syv punkter i spørgsmålet op ét for ét med et klart ja/nej. Det tilføjer kun kort, relevant forklaring om, hvad vurderingen i stedet omfatter."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver identificerbare kilder: SU-loven (LBK nr. 395 af 2023, § 7, stk. 1, nr. 1) og Vejledning nr. 10157 af 5. oktober 2026. Udsagnene er knyttet til dem med numre."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Vejledningen findes og er aktuel og autoritativ. SU-lov-henvisningen er til § 7, stk. 1, nr. 1, men handicaptillægget følger af § 7, stk. 3 i de frosne bestemmelser. Den angivne lovbestemmelse er derfor ikke den anvendelige kilde, og lovversionen LBK 395/2023 passer ikke med den frosne aktuelle kilde."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De fleste 'nej'-udsagn understøttes af vejledningspassagerne 203-210 og 228-233. Udsagnet om 'meget betydelige begrænsninger' er knyttet til § 7, stk. 1, nr. 1, som ikke støtter det. Udsagnet om, at man ser på 'andre typer arbejde, evt. med skånehensyn eller i mindre omfang', støttes ikke af de viste passager, som kun siger 'arbejdets karakter i forhold til funktionsnedsættelsen'. Numrene er desuden ikke tydeligt koblet til bestemte passager."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Svaret tilføjer ingen ny væsentlig regel eller myndighed. Omtalen af skånehensyn og mindre omfang ved andre jobtyper ligger i rubrikkens supporting elements og er ikke i strid med kilderne. 'I mindre omfang' er svagt belagt i det udleverede materiale, men ikke væsentligt."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer, at tidligere arbejde 'kan' indgå, og at der ses på arbejdets karakter, hvis den uddannelsessøgende er ophørt på grund af funktionsnedsættelsen. Det udelukker ikke alle skånehensyn generelt og gør ikke arbejdsprøvning eller indretning obligatorisk."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Punktgennemgangen og konklusionen hænger sammen. Ingen af de nævnte momenter er selvstændige kriterier, og den centrale vurdering er den konkrete evne til erhvervsarbejde som uddannelsessøgende. Der er ingen modstrid."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Modaliteten er præcis. 'Indgår ikke' og 'kontakter ikke' gengiver vejledningens kategoriske udelukkelser. 'Kan indgå' om tidligere arbejde og 'det mest nærliggende' i konklusionen gør ikke skøn eller undtagelser absolutte."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "partial",
      "reason": "Svaret dækker 'meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde', erhvervsevne med de ressourcer, personen har, arbejdsprøvning/indretning, arbejdsgivere, studierelevans, lokale forhold og erhvervsevne efter uddannelsen. Det nævner ikke ordblindeeksemplet eller udtrykkeligt, at det ikke indgår, om det er svært at finde egnet arbejde."
    }
  },
  "overall_notes": "Indholdet er juridisk korrekt og fuldstændigt i forhold til rubrikken. Svagheden ligger i kildeangivelsen. SU-lov-henvisningen peger på § 7, stk. 1, nr. 1 i stedet for stk. 3. En detalje om skånehensyn og mindre omfang er ikke dækket af de viste vejledningspassager. Derfor er C05 og C06 not_met, mens de øvrige kriterier er met."
}

